class ServersGroup extends HttpApiGroup.make("servers")
  .add(HttpApiEndpoint.post("serversPost", "/v2.1/servers", { payload: [HttpApiSchema.NoContent, ServersPostRequestJson], success: ServersPost202.pipe(HttpApiSchema.status(202)), error: [HttpApiSchema.Empty(400), HttpApiSchema.Empty(403), HttpApiSchema.Empty(409)] })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers:post")
      .annotate(OpenApi.Summary, "Create Server")
      .annotate(OpenApi.Description, "Creates a server.\n\nThe progress of this operation depends on the location of the\nrequested image, network I/O, host load, selected flavor, and other\nfactors.\n\nTo check the progress of the request, make a `GET /servers/{id}`\nrequest. This call returns a progress attribute, which is a percentage\nvalue from 0 to 100.\n\nThe `Location` header returns the full URL to the newly created\nserver and is available as a `self` and `bookmark` link in the\nserver representation.\n\nWhen you create a server, the response shows only the server ID, its\nlinks, and the admin password. You can get additional attributes\nthrough subsequent `GET` requests on the server.\n\nInclude the `block_device_mapping_v2` parameter in the create\nrequest body to boot a server from a volume.\n\nInclude the `key_name` parameter in the create request body to add a\nkeypair to the server when you create it. To create a keypair, make a\n[create keypair](https://docs.openstack.org/api-ref/compute/#create-or-import-keypair)\nrequest.\n\n**Preconditions**\n\n**Asynchronous postconditions**\n\n**Troubleshooting**\n\nNormal response codes: 202\n\nError response codes: badRequest(400), unauthorized(401),\nforbidden(403), itemNotFound(404), conflict(409)"), 
    HttpApiEndpoint.get("serversDetailGet", "/v2.1/servers/detail", { query: ServersDetailGetQuery, success: ServersDetailGet200, error: [HttpApiSchema.Empty(400), HttpApiSchema.Empty(403)] })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/detail:get")
      .annotate(OpenApi.Summary, "List Servers Detailed")
      .annotate(OpenApi.Description, "For each server, shows server details including config drive,\nextended status, and server usage information.\n\nThe extended status information appears in the OS-EXT-STS:vm_state,\nOS-EXT-STS:power_state, and OS-EXT-STS:task_state attributes.\n\nThe server usage information appears in the OS-SRV-USG:launched_at and\nOS-SRV-USG:terminated_at attributes.\n\nHostId is unique per account and is not globally unique.\n\nNormal response codes: 200\n\nError response codes: badRequest(400), unauthorized(401),\nforbidden(403)"), 
    HttpApiEndpoint.get("serversIdGet", "/v2.1/servers/:id", { success: ServersIdGet200, error: HttpApiSchema.Empty(404) })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/id:get")
      .annotate(OpenApi.Summary, "Show Server Details")
      .annotate(OpenApi.Description, "Shows details for a server.\n\nIncludes server details including configuration drive, extended status, and server usage information.\n\nThe extended status information appears in the `OS-EXT-STS:vm_state`, `OS-EXT-STS:power_state`, and `OS-EXT-STS:task_state` attributes.\n\nThe server usage information appears in the `OS-SRV-USG:launched_at` and `OS-SRV-USG:terminated_at` attributes.\n\nHostId is unique per account and is not globally unique.\n\n**Preconditions**\n\nThe server must exist.\n\nNormal response codes: 200\n\nError response codes: unauthorized(401), forbidden(403),\nitemNotFound(404)"), 
    HttpApiEndpoint.delete("serversIdDelete", "/v2.1/servers/:id", { success: HttpApiSchema.Empty(204), error: [HttpApiSchema.Empty(404), HttpApiSchema.Empty(409)] })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/id:delete")
      .annotate(OpenApi.Summary, "Delete Server")
      .annotate(OpenApi.Description, "Deletes a server.\n\nBy default, the instance is going to be (hard) deleted immediately from\nthe system, but you can set `reclaim_instance_interval` > 0 to make\nthe API soft delete the instance, so that the instance won’t be\ndeleted until the `reclaim_instance_interval` has expired since the\ninstance was soft deleted. The instance marked as `SOFT_DELETED` can\nbe recovered via `restore` action before it’s really deleted from the\nsystem.\n\n**Preconditions**\n\n**Asynchronous postconditions**\n\n**Troubleshooting**\n\nNormal response codes: 204\n\nError response codes: unauthorized(401), forbidden(403),\nitemNotFound(404), conflict(409)"), 
    HttpApiEndpoint.post("serversIdActionPost", "/v2.1/servers/:id/action", { payload: [HttpApiSchema.NoContent, ServersIdActionPostRequestJson], success: [ServersIdActionPost201.pipe(HttpApiSchema.status(201)), ServersIdActionPost202.pipe(HttpApiSchema.status(202)), HttpApiSchema.Empty(204)], error: [HttpApiSchema.Empty(400), HttpApiSchema.Empty(401), HttpApiSchema.Empty(403), HttpApiSchema.Empty(404), HttpApiSchema.Empty(409), HttpApiSchema.Empty(410), HttpApiSchema.Empty(501)] })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/id/action:post"), 
    HttpApiEndpoint.get("serversServerIdMetadataGet", "/v2.1/servers/:server_id/metadata", { success: ServersServerIdMetadataGet200, error: HttpApiSchema.Empty(404) })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/server_id/metadata:get")
      .annotate(OpenApi.Summary, "List All Metadata")
      .annotate(OpenApi.Description, "Lists all metadata for a server.\n\nPolicy defaults enable only users with the administrative role or the owner of the server to perform this operation. Cloud providers can change these permissions through the `policy.json` file.\n\nNormal response codes: 200\n\nError response codes: unauthorized(401), forbidden(403), itemNotFound(404)"), 
    HttpApiEndpoint.put("serversServerIdMetadataPut", "/v2.1/servers/:server_id/metadata", { payload: [HttpApiSchema.NoContent, ServersServerIdMetadataPutRequestJson], success: ServersServerIdMetadataPut200, error: [HttpApiSchema.Empty(403), HttpApiSchema.Empty(404), HttpApiSchema.Empty(409)] })
      .middleware(ApiKeyAuthSecurityMiddleware)
      .annotate(OpenApi.Identifier, "servers/server_id/metadata:put")
      .annotate(OpenApi.Summary, "Replace Metadata Items")
      .annotate(OpenApi.Description, "Replaces one or more metadata items for a server.\n\nCreates any metadata items that do not already exist in the server. Removes and completely replaces any metadata items that already exist in the server with the metadata items in the request.\n\nPolicy defaults enable only users with the administrative role or the owner of the server to perform this operation. Cloud providers can change these permissions through the `policy.json` file.\n\nNormal response codes: 200\n\nError response codes: badRequest(400), unauthorized(401), forbidden(403),\nitemNotFound(404), conflict(409)")) {}

